  const rows=useMemo(()=>(snapshot?.rows_by_model[model]??[]).filter(row=>!query.trim()||row.symbol.includes(query.trim())).sort((a,b)=>a.rank-b.rank),[snapshot,model,query]);
  const capitalValue=Math.max(0,Number(capital)||0);
  const target=v126?.target_portfolio_A;
